let entries=[],user=null,map,base,groups={},draft=null,drawLayer,locationLayer,mode=null,tab='mapa',loading=false,saving=false,practice=null,undoEntry=null,toastTimer,undoTimer,weatherRequest=0,importQueue=[];
const visible=e=>!e.deleted_at;const active=kind=>entries.filter(e=>visible(e)&&e.kind===kind);const draftKey=()=>`paleando:0.1:draft:${user?.id||'guest'}`;
function state(text){$('#save-state').textContent=text;}
function toast(message,undo=false){clearTimeout(toastTimer);$('#toast span').textContent=message;$('#toast').hidden=false;$('#undo').hidden=!undo;if(!undo&&undoEntry)$('#undo').hidden=false;if(!undo&&!undoEntry)toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
function openDialog(id){const d=$(id);if(!d.open)d.showModal();d.setAttribute('aria-label',d.querySelector('h2')?.textContent||'Paleando Menorca');}
function content(title,html){windyDispose?.();windyDispose=null;forecastView=null;forecastRenderVersion++;photoRequest++;weatherRequest++;$('#content-title').textContent=title;$('#content-body').innerHTML=html;openDialog('#content-dialog');}
function errorText(e){return e?.message||'No se pudo completar la operación. Inténtalo de nuevo.';}
function closeDialogs(){windyDispose?.();windyDispose=null; $$('dialog[open]').forEach(d=>d.close());$('#menu-button').setAttribute('aria-expanded','false');}
function switchTab(name){if(name!=='mapa'&&weatherSelection){const previous=weatherSelection;weatherSelection=null;restoreMapMode(previous);}if(practice&&!['mapa','diario'].includes(name))return;tab=name;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));$$('.view').forEach(v=>v.hidden=v.id!==`view-${name}`);if(name==='mapa')setTimeout(()=>map?.invalidateSize(),60);if(name==='diario')renderDiary();if(name==='progreso')renderProgress();}
function requireAccount(){if(practice)return true;if(!user){closeDialogs();openDialog('#auth-dialog');return false;}if(loading){toast('Espera a que termine la carga del diario.');return false;}return true;}
let syncVersion=0,accountEpoch=0,loginGuidePending=false,loadedAccount=null;
async function sync(){if(!user||saving||practice)return;const expectedUser=user.id,version=++syncVersion;loading=true;state('Cargando tu diario…');try{const data=await loadEntries();if(user?.id!==expectedUser||version!==syncVersion)return;loadedAccount=expectedUser;entries=data;state('Guardado en tu cuenta');render();return true;}catch(e){state('Error al cargar · pulsa Actualizar');toast(errorText(e));}finally{if(version===syncVersion)loading=false;}}
async function persist(entry){const existing=entries.find(e=>e.id===entry.id);const lifecycleOnly=existing&&existing.revision===entry.revision&&existing.kind===entry.kind&&existing.title===entry.title&&JSON.stringify(existing.data)===JSON.stringify(entry.data)&&existing.deleted_at!==entry.deleted_at;if(!lifecycleOnly)validateEntry(entry);if(practice){const saved={...structuredClone(entry),revision:(entry.revision||0)+1};const i=entries.findIndex(e=>e.id===entry.id);if(i<0)entries.unshift(saved);else entries[i]=saved;return saved;}if(!user)throw Error('Inicia sesión para guardar.');const owner=user.id,epoch=accountEpoch;state('Guardando…');try{const saved=await saveEntry(entry,owner);if(user?.id!==owner||epoch!==accountEpoch)throw Error('La sesión ha cambiado. Vuelve a abrir tu borrador en la cuenta original.');const i=entries.findIndex(e=>e.id===saved.id);if(i<0)entries.unshift(saved);else entries[i]=saved;state('Guardado en tu cuenta');return saved;}catch(e){if(epoch===accountEpoch)state(navigator.onLine?'Error de guardado · conserva tu borrador':'Pendiente de conexión · reintenta Guardar');throw e;}}
function stashDraft(){if(practice){$('#resume-draft').hidden=!draft;return true;}try{if(draft)localStorage.setItem(draftKey(),JSON.stringify(draft));else localStorage.removeItem(draftKey());$('#continue-draft').hidden=!draft;$('#resume-draft').hidden=!draft;return true;}catch{toast('No se ha podido conservar el borrador. Mantén esta pantalla abierta.');return false;}}
function recoverDraft(){try{const saved=JSON.parse(localStorage.getItem(draftKey())||'null');draft=saved&&['trip','plan'].includes(saved.kind)&&saved.data&&Array.isArray(saved.data.points)?saved:null;if(draft){draft.data.markers||=[];draft.data.photos||=[];}}catch{draft=null;}$('#continue-draft').hidden=!draft;}
function newEntry(kind='trip'){if(!requireAccount())return;if(draft){toast('Tienes un borrador. Continúa editándolo o descártalo desde la ficha.');showEditor();return;}draftItemUndos=[];draft={id:crypto.randomUUID(),kind,title:'',data:{date:today(),points:[],source:'manual',roundtrip:false,markers:[],photos:[]}};stashDraft();closeDialogs();beginDraw();}
function readForm(){if(!draft)return;const f=$('#entry-form');for(const name of ['date','duration','rating','wind','sea','notes','access'])draft.data[name]=f.elements[name].value;draft.title=f.elements.title.value;draft.data.roundtrip=f.elements.roundtrip.checked;draft.data.favorite=f.elements.favorite.checked;if(draft.kind==='plan'){draft.data.paceMinutesPerKm=Number(f.elements.pace.value);draft.data.stopMinutes=Number(f.elements.stops.value);if(draft.data.estimateMode==='manual')draft.data.estimatedMinutes=Number(f.elements.estimate.value);refreshEstimate();}stashDraft();}
function showEditor(){if(weatherSelection){const previous=weatherSelection;weatherSelection=null;restoreMapMode(previous);}if(!draft)return;mode=null;$('#draw-bar').hidden=true;$('#map-hint').hidden=true;closeDialogs();const f=$('#entry-form');f.reset();f.elements.id.value=draft.id;f.elements.title.value=draft.title;for(const name of ['date','duration','rating','wind','sea','notes','access'])f.elements[name].value=draft.data[name]||'';f.elements.roundtrip.checked=!!draft.data.roundtrip;f.elements.favorite.checked=!!draft.data.favorite;$('#editor-type').textContent=practice?'SALIDA DE PRÁCTICA':draft.kind==='plan'?'RUTA PENDIENTE':draft.revision?'EDITAR SALIDA':'NUEVA SALIDA';$('#save-entry').textContent=draft.kind==='plan'?'Guardar ruta pendiente':practice?'Guardar en la práctica':'Guardar salida';$('#editor-message').textContent='';$('#photo-input').disabled=false;prepareEstimate();renderDraft();openDialog('#editor-dialog');}
function renderDraft(){if(!draft)return;if(draft.kind==='plan')refreshEstimate();$('#route-type').textContent=routeStyle(draft).icon+' '+routeStyle(draft).label;$('#route-type').style.setProperty('--route-color',routeStyle(draft).color);$('#route-summary').textContent=measuredTripKm(draft.data)===null?'Trazado incompleto o no válido · puedes volver a dibujarlo o importar GPX':`${number(tripKm(draft.data))} km · ${draft.data.points.length} puntos${draft.data.source==='gpx'?' · GPX completo':draft.data.source==='coastal'?' · siguiendo la costa':''}${draft.data.snapMetres>25?' · ajuste a costa '+Math.round(draft.data.snapMetres)+' m':''}`;$('#draft-markers').innerHTML=(draft.data.markers||[]).map(m=>`<div class="route-summary"><span>${symbols[m.category]} ${esc(m.title)}</span><select aria-label="Fotografía de ${esc(m.title)}" data-marker-photo="${esc(m.id)}"><option value="">Sin fotografía</option>${(draft.data.photos||[]).map(p=>`<option value="${esc(p.id)}" ${m.photoId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button type="button" class="text-button danger" data-remove-marker="${esc(m.id)}">Quitar</button></div>`).join('')||'<p class="muted">Accesos, aparcamientos y rincones que recordar.</p>';$('#draft-photos').innerHTML=(draft.data.photos||[]).map(p=>`<figure><button type="button" class="text-button" data-photo="${esc(p.path||'example')}" data-photo-name="${esc(p.name)}">▧ ${esc(p.name)}</button><button type="button" data-remove-photo="${esc(p.id)}" class="text-button danger">Quitar de la galería</button></figure>`).join('');hydratePhotos($('#draft-photos'));renderItemUndos();drawDraft();}
function beginDraw(marker=false){if(!marker&&(!Array.isArray(draft.data.points)||draft.data.points.some(p=>!validPoint(p)))){if(!confirm('El trazado necesita reparación. ¿Reiniciar solo el recorrido de este borrador? La ficha guardada se conserva hasta que pulses Guardar.'))return;draft.data={...draft.data,points:[],anchors:[],source:'coastal'};stashDraft();}if(!marker&&draft?.data.source==='gpx'){if(!confirm('¿Sustituir el trazado GPX por una ruta costera nueva?'))return;draft.data={...draft.data,points:[],anchors:[],source:'coastal'};stashDraft();}if(!marker&&draft?.data.source==='manual'&&draft.data.points.length>=2){try{const anchors=structuredClone(draft.data.points);draft.data={...draft.data,...coastalPath(anchors),anchors,source:'coastal'};stashDraft();}catch(error){toast(errorText(error));}}if(!map){toast('El mapa no ha cargado. Reintenta al recuperar la conexión.');return;}closeDialogs();switchTab('mapa');mode=marker?'marker':'route';$('#draw-bar').hidden=false;$('#draw-label').textContent=marker?'Toca dónde añadir el marcador':draft.data.points.length?'Añade un punto de paso junto a la costa':'Toca salida y llegada junto a la costa';$('#finish-draw').hidden=marker;$('#remove-point').hidden=marker;$('#map-hint').textContent=marker?'Un toque coloca el marcador; el recorrido no cambia.':'Marca salida y llegada. El trazado seguirá la costa; puedes añadir puntos de paso.';$('#map-hint').hidden=false;$('#map-wrap').scrollIntoView({behavior:'smooth',block:'center'});drawDraft();if(marker)guideAdvance('marker-start');}
function initMap(){if(!globalThis.L){$('.map-loading').textContent='No se pudo cargar el mapa. Comprueba la conexión y vuelve a abrir la página.';return;}$('#map').innerHTML='';map=L.map('map',{zoomControl:false}).setView([39.98,4.08],10);map.attributionControl?.addAttribution('Costa: IDEIB · GOIB / SITIBSA · MTIB 2012');setBase('terrain');for(const key of ['trips','plans',...Object.keys(categories)])groups[key]=L.layerGroup().addTo(map);drawLayer=L.layerGroup().addTo(map);locationLayer=L.layerGroup().addTo(map);selectionLayer=L.layerGroup().addTo(map);weatherLayer=L.layerGroup().addTo(map);map.on('resize',()=>{if(selectedRouteId)fitSelectedRoute();});map.on('click',e=>{const selectedLatLng=e.originalEvent&&map.mouseEventToLatLng?map.mouseEventToLatLng(e.originalEvent):e.latlng;if(mode==='weather'){selectWeatherPoint([selectedLatLng.lat,selectedLatLng.lng]);return;}if(!draft||!mode)return;if(mode==='marker'){if(practice)practice.markerPoint=[selectedLatLng.lat,selectedLatLng.lng];mode=null;$('#draw-bar').hidden=true;$('#map-hint').hidden=true;markerForm([selectedLatLng.lat,selectedLatLng.lng],true);guideAdvance('marker-point');return;}try{draft.data=appendCoastalPoint(draft.data,[selectedLatLng.lat,selectedLatLng.lng]);if(draft.kind==='plan')draft.data=updatePlanEstimate(draft.data,active('preferences')[0]?.data||{});}catch(error){toast(errorText(error));return;}stashDraft();drawDraft();$('#draw-label').textContent=draft.data.points.length<2?'Salida marcada · toca la llegada':`${number(tripKm(draft.data))} km por la costa · ${draft.data.points.length} puntos${draft.data.snapMetres>25?' · ajuste '+Math.round(draft.data.snapMetres)+' m':''}`;if(practice&&draft.data.points.length>=2&&tripKm(draft.data)>.01)guideAdvance('points');});map.on('moveend',()=>{if(!practice)return;});let tileErrors=0;map.on('baselayerchange',()=>tileErrors=0);map._tileError=()=>{if(++tileErrors===3)toast('No se está cargando la cartografía. Comprueba la conexión o cambia la base en Capas.');};}
function setBase(value){if(!map)return;if(base)map.removeLayer(base);if(value==='satellite')base=L.tileLayer.wms('https://www.ign.es/wms-inspire/pnoa-ma',{layers:'OI.OrthoimageCoverage',format:'image/jpeg',attribution:'Ortofoto © IGN · PNOA',maxZoom:20});else if(value==='streets')base=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19});else base=L.tileLayer('https://tile.opentopomap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap · <a href="https://opentopomap.org">OpenTopoMap</a> (CC-BY-SA)',maxZoom:17});base.on('tileerror',()=>map._tileError?.());base.addTo(map);}
function drawDraft(){if(!drawLayer)return;drawLayer.clearLayers();if(!draft)return;const points=draft.data.points;if(!Array.isArray(points)||!points.every(validPoint))return;if(points.length){L.polyline(points,{color:routeStyle(draft).color,weight:5,dashArray:'8 6'}).addTo(drawLayer);[points[0],...(points.length>1?[points.at(-1)]:[])].forEach(p=>L.marker(p,{interactive:false,icon:L.divIcon({className:'route-point',iconSize:[16,16]})}).addTo(drawLayer));}}
function renderMap(){if(!map)return;Object.values(groups).forEach(g=>g.clearLayers());for(const e of entries.filter(visible)){if(['trip','plan'].includes(e.kind)&&validGeometry(e.data.points)){const line=L.polyline(e.data.points,{color:routeStyle(e).color,weight:4,opacity:.85,dashArray:e.kind==='plan'?'6 6':null}).addTo(groups[e.kind==='trip'?'trips':'plans']);line.on('click',ev=>{if(mode)return;L.DomEvent.stopPropagation(ev);detail(e.id);});if(e.kind==='trip')for(const m of e.data.markers||[])addMarker(m,e.id);}if(e.kind==='place')addMarker({...e.data,id:e.id,title:e.title});}drawDraft();refreshSelectedRoute();}
function addMarker(m,routeId){if(!validPoint(m.point)||!groups[m.category])return;const marker=L.marker(m.point,{bubblingMouseEvents:true,icon:L.divIcon({className:'',html:`<div class="place-pin">${symbols[m.category]}</div>`,iconSize:[32,32],iconAnchor:[16,16]})}).addTo(groups[m.category]);marker.on('click',ev=>{if(mode)return;L.DomEvent.stopPropagation(ev);if(routeId)detail(routeId);else placeDetail(m.id);});marker.bindTooltip(esc(m.title));}
function render(){const realEntries=practice?practice.entries:entries;const a=aggregate(realEntries),c=coastProgress(realEntries);$('#total-km').textContent=number(a.km);$('#trip-count').textContent=a.count?`${a.count} ${a.count===1?'salida guardada':'salidas guardadas'}`:'Sin salidas todavía';$('#coast-total').textContent=number(c.totalKm);$('#coast-covered').textContent=number(c.coveredKm);$('#energy').style.width=`${c.percent}%`;$('.energy-track').setAttribute('aria-valuenow',c.percent.toFixed(4));$('.energy-track').setAttribute('aria-valuetext',`${number(c.coveredKm)} de ${number(c.totalKm)} kilómetros de costa recorridos, ${number(c.percent)} por ciento`);$('#goal-copy').textContent=`Costa pendiente: ${number(c.pendingKm)} km`;$('#goal-percent').textContent=c.percent>0&&c.percent<.01?'< 0,01 %':`${number(c.percent)} %`;const notes=[];if(a.invalidCount)notes.push(`${a.invalidCount} ${a.invalidCount===1?'salida necesita':'salidas necesitan'} revisar su trazado`);if(c.unmatched)notes.push(`${c.unmatched} ${c.unmatched===1?'recorrido sin coincidencia costera':'recorridos sin coincidencia costera'}`);if(c.gps)notes.push('Cobertura GPX estimada');$('#coast-status').textContent=notes.join(' · ');$('#coast-status').hidden=!notes.length;$('#account-button').textContent=user?'Mi cuenta ↗':'Entrar ↗';$('#logout').hidden=!user;$('#continue-draft').hidden=!draft;$('#resume-draft').hidden=!draft;renderMap();renderDiary();if(tab==='progreso')renderProgress();}
function coastInfo(){const c=coastProgress(practice?practice.entries:entries);content('Tu costa, sin contar dos veces',`<p><strong>${number(c.totalKm)} km</strong> de costa de referencia, calculados desde la geometría principal conectada que utiliza la app.</p><p>Las salidas realizadas cubren los tramos por los que has pasado. La unión de esos tramos cuenta cada parte una sola vez, aunque repitas salida o regreses por el mismo sitio.</p><p>Los kilómetros paleados sí incluyen todas las repeticiones y la vuelta. Las rutas pendientes y las salidas eliminadas no suman.</p><h3>Recorridos GPX</h3><p>Su distancia paleada conserva el recorrido original. Su cobertura de costa es una estimación: solo se acreditan tramos paralelos a la huella GPS y a menos de 75 m. No se unen automáticamente sus extremos bordeando calas que el GPX no recorre.</p><h3>Cartografía de referencia</h3><p><a href="${coastalSource.url}" target="_blank" rel="noopener">${coastalSource.name}</a>. Geometría simplificada a 2,5 m. Esta longitud depende de la escala y de la geometría utilizada; no es una longitud oficial universal ni incluye todos los islotes.</p>`);}

function empty(title,copy,action='new'){return `<div class="empty-state"><div class="empty-icon">⌁</div><h3>${title}</h3><p>${copy}</p>${action?`<button class="button primary" data-action="${action}">${action==='new'?'＋ Guardar mi primera salida':action==='new-place'?'＋ Añadir lugar':'＋ Planificar ruta'}</button>`:''}</div>`;}
function entryCard(e){return `<article class="card"><div class="card-top"><span>${esc(e.data.date||'Sin fecha')}</span><span class="route-badge" style="--route-color:${routeStyle(e).color}">${routeStyle(e).icon} ${routeStyle(e).label}${e.data.favorite?' · ★':''}</span></div><h3>${esc(e.title)}</h3><div class="card-stat">${measuredTripKm(e.data)===null?'No disponible':number(tripKm(e.data))+' <small>km</small>'}</div><p>${esc((e.data.notes||'Un recuerdo más en tu cuaderno de mar.').slice(0,110))}</p><div class="actions"><button class="text-button" data-action="view-adventure" data-id="${e.id}">Ver aventura ↗</button><button class="text-button" data-action="detail" data-id="${e.id}">Ficha</button><button class="text-button" data-action="edit" data-id="${e.id}">Editar</button></div></article>`;}
function renderDiary(){const selected=$('#year-filter').value;const years=[...new Set(active('trip').map(e=>e.data.date?.slice(0,4)).filter(Boolean))].sort().reverse();$('#year-filter').innerHTML='<option value="">Todos los años</option>'+years.map(y=>`<option ${selected===y?'selected':''}>${y}</option>`).join('');const q=$('#trip-search').value.toLocaleLowerCase('es');const list=active('trip').filter(e=>(!selected||e.data.date?.startsWith(selected))&&(!$('#favorites-filter').checked||e.data.favorite)&&`${e.title} ${e.data.notes||''}`.toLocaleLowerCase('es').includes(q)).sort((a,b)=>String(b.data.date||'').localeCompare(String(a.data.date||'')));$('#trip-list').innerHTML=list.map(entryCard).join('')||empty(active('trip').length?'Sin resultados':'Aquí empieza tu historia',active('trip').length?'Prueba con otro filtro.':'Todavía no hay salidas. Tu próxima aventura tiene sitio aquí.',active('trip').length?'':'new');}
function renderProgress(){const realEntries=practice?practice.entries:entries,year=String(new Date().getFullYear()),a=aggregate(realEntries,year),all=aggregate(realEntries),c=coastProgress(realEntries),max=Math.max(1,...a.months),months=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];$('#progress-content').innerHTML=`<div class="progress-cards coast-progress-cards"><div class="card"><span>Costa total</span><strong>${number(c.totalKm)} km</strong></div><div class="card"><span>Costa recorrida · sin repetir</span><strong>${number(c.coveredKm)} km</strong></div><div class="card"><span>Costa pendiente</span><strong>${number(c.pendingKm)} km</strong></div><div class="card"><span>Distancia paleada · todas las salidas</span><strong>${number(all.km)} km</strong></div></div><button class="text-button" data-action="coast-info">Cómo se calcula la costa ⓘ</button><div class="card"><h3>Tu año en el agua · ${year}</h3><p class="muted">${a.count} salidas · ${number(a.km)} km paleados · ${number(a.minutes/60)} h registradas</p>${months.map((m,i)=>`<div class="month-row"><span>${m}</span><div class="month-bar"><i style="width:${a.months[i]/max*100}%"></i></div><span>${number(a.months[i])} km</span></div>`).join('')}</div><button class="text-button" data-action="goal">＋ Mi objetivo anual de kilómetros</button>`;}

function edit(id){if(!requireAccount())return;const e=entries.find(e=>e.id===id);if(!e)return;if(draft&&draft.id!==id){toast('Resuelve el borrador abierto antes de editar otra salida.');showEditor();return;}draft=structuredClone(e);if(practice)practice.beforeEdit=JSON.stringify(draft);stashDraft();showEditor();guideAdvance('edit');}
function detail(id){const e=entries.find(e=>e.id===id);if(!e)return;content(e.title,`<span class="badge route-badge" style="--route-color:${routeStyle(e).color}">${routeStyle(e).icon} ${routeStyle(e).label} · ${esc(e.data.date)}</span><h3>${measuredTripKm(e.data)===null?'Distancia no disponible':number(tripKm(e.data))+' km'} ${e.data.roundtrip?'· Ida y vuelta':''}</h3><dl class="detail-dl"><dt>${e.kind==='plan'?'Duración estimada':'Duración real'}</dt><dd>${e.kind==='plan'?durationText(e.data.estimatedMinutes):durationText(e.data.duration)}</dd><dt>Acceso al mar</dt><dd>${esc(({easy:'Fácil',medium:'Con precaución',hard:'Difícil'})[e.data.access]||'Sin registrar')}</dd><dt>Viento observado</dt><dd>${esc(e.data.wind||'Sin registrar')}</dd><dt>Estado del mar</dt><dd>${esc(e.data.sea||'Sin registrar')}</dd><dt>Valoración</dt><dd>${e.data.rating?'★'.repeat(Math.max(0,Math.min(5,Number(e.data.rating)||0))):'Sin valorar'}</dd></dl><p style="white-space:pre-wrap">${esc(e.data.notes||'Sin notas')}</p><h3>Marcadores</h3>${(e.data.markers||[]).map(m=>`<p>${symbols[m.category]} ${esc(m.title)} · ${esc(categories[m.category])}${m.photoId?` <button class="text-button" data-action="marker-photo" data-id="${e.id}" data-marker="${esc(m.id)}">Ver foto</button>`:''}</p>`).join('')||'<p class="muted">Sin marcadores</p>'}<div class="photo-grid">${(e.data.photos||[]).map(p=>`<button class="text-button" data-photo="${esc(p.path||'example')}" data-photo-name="${esc(p.name)}">▧ ${esc(p.name)}</button>`).join('')}</div><div class="actions"><button class="button primary" data-action="edit" data-id="${e.id}">Editar</button> <button class="text-button" data-action="locate" data-id="${e.id}">Ver en mapa</button> <button class="text-button" data-action="export" data-id="${e.id}">Exportar GPX</button> ${e.kind==='plan'?`<button class="text-button" data-action="complete" data-id="${e.id}">Registrar como realizada</button>`:''}<button class="text-button danger" data-action="delete" data-id="${e.id}">Eliminar</button></div>`);hydratePhotos($('#content-body'));guideAdvance('detail');}
async function deleteEntry(id){if(saving)return;if(undoEntry){toast('Primero deshaz la eliminación anterior o espera a que termine su plazo.',true);return;}const e=entries.find(e=>e.id===id);if(!e)return;if(draft){toast('Resuelve el borrador abierto antes de eliminar elementos.');return;}if(!confirm(`¿Eliminar «${e.title}»? Dejará de aparecer y se recalculará el progreso. Las fotografías no se borrarán del almacenamiento. Puedes deshacer durante 30 segundos.`))return;saving=true;try{const saved=await persist({...e,deleted_at:new Date().toISOString()});undoEntry={id:saved.id,until:Date.now()+30000};closeDialogs();render();toast(`«${e.title}» eliminado.`,true);clearTimeout(undoTimer);undoTimer=practice?null:setTimeout(()=>{undoEntry=null;$('#toast').hidden=true;},30000);guideAdvance('delete');}catch(e){toast(errorText(e));}finally{saving=false;}}
async function undo(){if(!undoEntry||saving)return;if(!practice&&Date.now()>undoEntry.until){undoEntry=null;toast('Ha terminado el plazo de recuperación.');return;}saving=true;try{const e=entries.find(e=>e.id===undoEntry.id);await persist({...e,deleted_at:null});undoEntry=null;clearTimeout(undoTimer);render();toast('Aventura recuperada.');guideAdvance('undo');}catch(e){toast(errorText(e),true);}finally{saving=false;}}
function showPlans(){guideAdvance('plans');closeDialogs();content('Aventuras por venir',`<p class="muted">Las rutas pendientes no suman kilómetros realizados.</p><button class="button primary" data-action="plan">＋ Planificar ruta</button><div class="card-grid" style="margin-top:20px">${active('plan').map(entryCard).join('')||empty('Un mar de posibilidades','Prepara una ruta y guárdala para otro día.','plan')}</div>`);}
function markerForm(point,route=false,existing=null){content(existing?'Editar lugar':route?'Un detalle para recordar':'Nuevo lugar',`<form id="place-form"><label>Nombre<input name="title" maxlength="180" required value="${esc(existing?.title||'')}" placeholder="Acceso junto al embarcadero"></label><label>Categoría<select name="category">${Object.entries(categories).map(([k,v])=>`<option value="${k}" ${existing?.data.category===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="form-row"><label>Latitud<input name="lat" type="number" step="any" min="-90" max="90" required value="${point?.[0]??''}"></label><label>Longitud<input name="lng" type="number" step="any" min="-180" max="180" required value="${point?.[1]??''}"></label></div><label>Notas<textarea name="notes">${esc(existing?.data.notes||'')}</textarea></label><p id="place-error" role="status"></p><button class="button primary">Guardar ${route?'marcador':'lugar'}</button></form>`);$('#place-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.target;if(saving)return;const p=[Number(form.lat.value),Number(form.lng.value)];if(!validPoint(p))return;const data={point:p,category:form.category.value,notes:form.notes.value},title=form.elements.title.value.trim();if(!title)return;if(route){draft.data.markers.push({id:crypto.randomUUID(),title,...data});stashDraft();showEditor();guideAdvance('marker');return;}if(!requireAccount())return;saving=true;try{await persist({...(existing||{}),id:existing?.id||crypto.randomUUID(),kind:'place',title,data});render();showPlaces();}catch(e){$('#place-error').textContent=errorText(e);}finally{saving=false;}};}
function allPlaces(){return [...active('place').map(e=>({...e.data,id:e.id,title:e.title})),...active('trip').flatMap(e=>(e.data.markers||[]).map(m=>({...m,routeId:e.id})))];}
function showPlaces(){guideAdvance('places');closeDialogs();content('Mis lugares',`<p class="muted">Tus accesos, aparcamientos y pequeños descubrimientos.</p><button class="button primary" data-action="new-place">＋ Añadir lugar</button><label>Buscar<input id="place-search" type="search" placeholder="Busca un rincón"></label><label>Categoría<select id="place-category"><option value="">Todas (${allPlaces().length})</option>${Object.entries(categories).map(([k,v])=>`<option value="${k}">${v} (${allPlaces().filter(m=>m.category===k).length})</option>`).join('')}</select></label><div id="place-list"></div>`);const list=()=>{const q=$('#place-search').value.toLowerCase(),cat=$('#place-category').value;$('#place-list').innerHTML=allPlaces().filter(m=>(!cat||m.category===cat)&&m.title.toLowerCase().includes(q)).map(m=>`<article class="route-summary" style="margin:10px 0"><span>${symbols[m.category]} ${esc(m.title)}<small class="muted"> · ${esc(categories[m.category])}</small></span><button class="text-button" data-action="${m.routeId?'route-place':'place-detail'}" data-id="${m.routeId||esc(m.id)}">Ver ficha ↗</button></article>`).join('')||'<p class="muted">No hay lugares que mostrar.</p>';};$('#place-search').oninput=list;$('#place-category').onchange=list;list();}
function placeDetail(id){const e=entries.find(e=>e.id===id);if(!e)return;content(e.title,`<span class="badge">${esc(categories[e.data.category])}</span><p>${number(e.data.point[0])}, ${number(e.data.point[1])}</p><p>${esc(e.data.notes||'Sin notas')}</p><button class="button primary" data-action="edit-place" data-id="${id}">Editar</button> <button class="text-button" data-action="windy-place" data-id="${id}">Abrir en Windy ↗</button> <button class="text-button danger" data-action="delete" data-id="${id}">Eliminar</button>`);}
function goalForm(){if(!requireAccount())return;closeDialogs();const year=new Date().getFullYear(),g=active('goal').find(e=>Number(e.data.year)===year);content('Un reto a tu medida',`<p>Cada aventura suma. Elige cuántos kilómetros te gustaría palear en ${year}.</p><form id="goal-form"><label>Objetivo anual (km)<input type="number" name="target" min="1" max="100000" step="1" value="${g?.data.target||100}" required></label><p id="goal-error" role="status"></p><button class="button primary">Guardar objetivo</button>${g?` <button class="text-button danger" type="button" data-action="delete" data-id="${g.id}">Eliminar objetivo</button>`:''}</form>`);$('#goal-form').onsubmit=async ev=>{ev.preventDefault();if(saving)return;saving=true;try{await persist({...(g||{}),id:g?.id||crypto.randomUUID(),kind:'goal',title:`Objetivo ${year}`,data:{year,target:Number(ev.target.elements.target.value)}});closeDialogs();render();toast('¡Reto preparado! Ahora, a disfrutar del camino.');}catch(e){$('#goal-error').textContent=errorText(e);}finally{saving=false;}};}
function captureMapMode(){return {mode,bar:$('#draw-bar').hidden,label:$('#draw-label').textContent,hint:$('#map-hint').textContent,hintHidden:$('#map-hint').hidden,finish:$('#finish-draw').hidden,remove:$('#remove-point').hidden,editor:$('#editor-dialog').open};}
function restoreMapMode(previous){if(!previous)return;$('#cancel-draw').setAttribute('aria-label','Cancelar trazado');mode=previous.mode;$('#draw-bar').hidden=previous.bar;$('#draw-label').textContent=previous.label;$('#map-hint').textContent=previous.hint;$('#map-hint').hidden=previous.hintHidden;$('#finish-draw').hidden=previous.finish;$('#remove-point').hidden=previous.remove;}
function weather(){if(!map){toast('El mapa no está disponible. Comprueba la conexión.');return;}if(weatherSelection)return;readFormIfOpen();weatherSelection=captureMapMode();closeDialogs();switchTab('mapa');$('#layers').hidden=true;$('[data-map=layers]').setAttribute('aria-expanded','false');mode='weather';$('#cancel-draw').setAttribute('aria-label','Cancelar selección del tiempo');$('#draw-label').textContent='Selecciona la ubicación del tiempo';$('#draw-bar').hidden=false;$('#finish-draw').hidden=true;$('#remove-point').hidden=true;$('#map-hint').textContent='Toca el mapa donde quieras consultar la previsión';$('#map-hint').hidden=false;$('#map-wrap').scrollIntoView({block:'center'});if(practice){$('.guide-card')?.remove();}}
function cancelWeatherSelection(){const previous=weatherSelection;weatherSelection=null;restoreMapMode(previous);if(previous?.editor)showEditor();if(practice)guideRender();}
let weatherReturn=null;
function markWeatherPoint(point){weatherMarkerPoint=[...point];weatherLayer?.clearLayers();if(weatherLayer)L.circleMarker(point,{radius:9,color:'#ffffff',weight:3,fillColor:'#2678c8',fillOpacity:1}).addTo(weatherLayer);}
function resetWeatherTransient(){weatherController?.abort();weatherController=null;weatherRequest++;forecastRenderVersion++;windyDispose?.();windyDispose=null;forecastView=null;weatherSelection=null;weatherReturn=null;weatherMarkerPoint=null;weatherLayer?.clearLayers();}
function selectWeatherPoint(point){if(!weatherSelection)return;weatherReturn=weatherSelection;weatherSelection=null;restoreMapMode(weatherReturn);markWeatherPoint(point);openForecast(point);}
function finishWeatherDialog(){windyDispose?.();windyDispose=null;forecastView=null;forecastRenderVersion++;weatherController?.abort();weatherRequest++;if(weatherReturn){const previous=weatherReturn;weatherReturn=null;restoreMapMode(previous);if(previous.editor)showEditor();}}
function directionMarkup(d){return d?`<span class="direction-arrow" aria-hidden="true" style="transform:rotate(${d.towards}deg)">↑</span> Viene del ${d.orientation} (${Math.round(d.degrees)}°)`:'No disponible';}
async function openForecast(point,wantedDay=null){weatherController?.abort();if($('#map-wrap').classList.contains('fullscreen-map')){$('#map-wrap').classList.remove('fullscreen-map');$('[data-map=fullscreen]').setAttribute('aria-label','Pantalla completa');$('[data-map=fullscreen]').setAttribute('aria-pressed','false');map.invalidateSize();}content('Previsión del punto seleccionado',`<p class="forecast-location">Ubicación seleccionada: <strong>${point.map(p=>p.toFixed(5)).join(', ')}</strong></p><nav class="forecast-days" aria-label="Día de la previsión"><button id="forecast-prev" class="icon-button" aria-label="Día anterior" disabled>←</button><strong id="forecast-day-label" aria-live="polite">Cargando días…</strong><button id="forecast-next" class="icon-button" aria-label="Día siguiente" disabled>→</button><button id="forecast-today" class="button secondary" disabled>Hoy</button></nav><label class="forecast-hour-label">Hora de la previsión (Menorca)<select id="forecast-hour" disabled></select></label><div id="weather-result" role="status">Consultando temperatura, viento y oleaje…</div><p class="field-note">Las flechas apuntan hacia donde se desplazan. La orientación indica de dónde vienen el viento y las olas. Una previsión no garantiza navegabilidad.</p><section class="windy-section"><h3>Mapa de Windy</h3><div id="windy-map"></div></section>`);windyDispose=mountWindy($('#windy-map'),point);const request=++weatherRequest,controller=new AbortController();weatherController=controller;let timedOut=false;const timeout=setTimeout(()=>{timedOut=true;controller.abort();},15000);try{const range=await fetchForecastRange(point,{signal:controller.signal});if(request!==weatherRequest||!$('#weather-result'))return;const days=availableDays(range),today=dayKey();forecastView={point:[...point],range,days,day:days.includes(wantedDay)?wantedDay:days.includes(today)?today:days[0],hour:null};if(!forecastView.day)throw Error('No hay días de previsión disponibles.');$('#forecast-prev').onclick=()=>changeForecastDay(-1);$('#forecast-next').onclick=()=>changeForecastDay(1);$('#forecast-today').disabled=!days.includes(today);$('#forecast-today').onclick=()=>selectForecastDay(today);$('#forecast-hour').onchange=()=>{if(forecastView){forecastView.hour=Number($('#forecast-hour').value);renderForecastDay();}};renderForecastDay();guideAdvance('weather');}catch(e){if(request!==weatherRequest||!$('#weather-result'))return;$('#forecast-day-label').textContent='Previsión no disponible';$('#weather-result').textContent=timedOut?'La consulta ha tardado demasiado. No hay una previsión actual disponible.':errorText(e);appendForecastRetry(point,wantedDay);if(practice){const b=document.createElement('button');b.className='text-button';b.textContent='Continuar la práctica sin previsión';b.onclick=()=>guideAdvance('weather');$('#weather-result').append(b);}}finally{clearTimeout(timeout);}}
function appendForecastRetry(point,day){const b=document.createElement('button');b.className='button secondary';b.textContent='Reintentar previsión';b.onclick=()=>openForecast(point,day);$('#weather-result').append(b);}
function changeForecastDay(delta){if(!forecastView)return;const index=forecastView.days.indexOf(forecastView.day)+delta;if(index>=0&&index<forecastView.days.length)selectForecastDay(forecastView.days[index]);}
function selectForecastDay(day){if(!forecastView||!forecastView.days.includes(day))return;forecastView.day=day;forecastView.hour=null;const generation=++forecastRenderVersion;updateForecastDayControls();$('#forecast-hour').disabled=true;$('#weather-result').textContent='Cargando los datos del día seleccionado…';setTimeout(()=>{if(generation===forecastRenderVersion&&forecastView?.day===day)renderForecastDay();},0);}
function updateForecastDayControls(){const view=forecastView;if(!view)return;const index=view.days.indexOf(view.day);$('#forecast-prev').disabled=index<=0;$('#forecast-next').disabled=index>=view.days.length-1;const date=new Date(view.day+'T12:00:00Z');const prefix=view.day===dayKey()?'Hoy · ':'';$('#forecast-day-label').textContent=prefix+date.toLocaleDateString('es-ES',{timeZone:'Europe/Madrid',weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#forecast-day-label').dataset.day=view.day;}
function renderForecastDay(){const view=forecastView;if(!view||!$('#weather-result'))return;updateForecastDayControls();const times=dayHours(view.range,view.day),hours=$('#forecast-hour');if(!times.includes(view.hour))view.hour=times.find(t=>Number(new Date(t*1000).toLocaleString('en-GB',{timeZone:'Europe/Madrid',hour:'2-digit',hour12:false}))>=12)||times[0]||null;hours.innerHTML=times.map(t=>`<option value="${t}" ${t===view.hour?'selected':''}>${new Date(t*1000).toLocaleTimeString('es-ES',{timeZone:'Europe/Madrid',hour:'2-digit',minute:'2-digit'})}</option>`).join('');hours.disabled=!times.length;if(view.hour===null){$('#weather-result').dataset.day=view.day;delete $('#weather-result').dataset.time;$('#weather-result').textContent='No disponible: no quedan horas futuras para este día. Selecciona otro día.';return;}const f=sampleForecast(view.range,view.hour),display=(v,unit)=>available(v)?`${esc(v)} ${unit}`:'No disponible';const date=new Date(f.time*1000).toLocaleString('es-ES',{timeZone:'Europe/Madrid',dateStyle:'full',timeStyle:'short'});$('#weather-result').dataset.day=view.day;$('#weather-result').dataset.time=f.time;$('#weather-result').innerHTML=`<p><strong>${esc(date)}</strong> · Hora de Menorca (Europe/Madrid)</p><dl class="forecast-grid"><dt>Temperatura</dt><dd>${display(f.temperature,'°C')}</dd><dt>Velocidad del viento</dt><dd>${display(f.windSpeed,'km/h')}</dd><dt>De dónde viene el viento</dt><dd>${directionMarkup(f.windDirection)}</dd><dt>Altura de las olas</dt><dd>${display(f.waveHeight,'m')}</dd><dt>De dónde vienen las olas</dt><dd>${directionMarkup(f.waveDirection)}</dd></dl>${f.marinePoint?`<p class="field-note">Punto marítimo del proveedor: ${f.marinePoint.map(p=>p.toFixed(5)).join(', ')} · Ajuste de ${number(distance([view.point,f.marinePoint])*1000)} m respecto al punto seleccionado.</p>`:'<p class="field-note">Ubicación marítima: No disponible.</p>'}<p class="field-note">Fuente: Open-Meteo · datos horarios consultados para este punto y esta fecha.</p>`;if(f.partial){const warning=document.createElement('p');warning.textContent='Uno de los proveedores no respondió. Los campos ausentes se muestran como No disponible.';$('#weather-result').append(warning);appendForecastRetry(view.point,view.day);}}
async function showPhoto(path,name){content(name,'<p id="photo-status" role="status">Cargando fotografía privada…</p>');const token=++photoRequest;try{const url=path==='example'?'./guide-photo.svg':await signedPhoto(path);if(token!==photoRequest||!$('#photo-status'))return;const img=document.createElement('img');img.className='photo-view';img.alt=name;img.src=url;img.onerror=()=>{if($('#photo-status'))$('#photo-status').textContent='No se pudo cargar la fotografía. Vuelve a intentarlo.';};img.onload=()=>$('#photo-status')?.remove();$('#content-body').append(img);}catch(e){if(token===photoRequest&&$('#photo-status'))$('#photo-status').textContent=errorText(e);}}let photoRequest=0;
function showHelp(){content('Aprende paleando',`<p>Un mapa, tus recuerdos y muchas ganas de mar.</p><h3>Tu primera salida</h3><p>Pulsa Nueva salida, marca salida y llegada junto a la costa y revisa el trazado costero antes de guardar. Puedes importar un GPX para conservar un recorrido registrado.</p><button class="button primary" data-action="practice">Empezar práctica dirigida</button><p class="field-note">La práctica utiliza datos separados y una imagen de ejemplo. No se guarda en el servidor.</p><h3>Qué está disponible en esta edición</h3><p>Diario privado, dibujo manual, GPX, lugares, fotografías, objetivos y previsión. El trazado sigue la costa de la cartografía IDEIB/GOIB. La barra muestra el porcentaje de costa recorrida sin repetir tramos, separado de los kilómetros paleados.</p><h3>Seguridad en el agua</h3><p>Consulta el viento, el estado del mar y los avisos. El mapa y las rutas dibujadas no garantizan navegabilidad.</p><h3>Versión 0.3.0</h3><p class="muted">28 acciones reales, práctica aislada, borradores por cuenta y fotografías privadas.</p>`);}
function preferences(){guideAdvance('preferences');if(!requireAccount())return;const p=active('preferences')[0];content('A tu manera',`<form id="preferences-form"><label class="checkbox-label"><input name="guide" type="checkbox" ${guideHidden()?'checked':''}> No mostrar de nuevo la guía al entrar</label><label>Ritmo para rutas pendientes (min/km)<input name="pace" type="number" min="1" max="240" step="0.5" value="${p?.data.paceMinutesPerKm||15}" required></label><p class="muted">Predeterminado: 15 min/km (4 km/h). Editable en cada ruta.</p><p class="muted">Unidades: kilómetros y minutos. Idioma: español.</p><p id="pref-message" role="status"></p><button class="button primary">Guardar preferencias</button></form>`);$('#preferences-form').onsubmit=async ev=>{ev.preventDefault();if(saving)return;saving=true;try{await persist({...(p||{}),id:p?.id||crypto.randomUUID(),kind:'preferences',title:'Preferencias',data:{...p?.data,paceMinutesPerKm:Number(ev.target.elements.pace.value),hideGuide:ev.target.guide.checked}});try{localStorage.setItem(`paleando:guide:hidden:${user.id}`,String(ev.target.guide.checked));}catch{}closeDialogs();toast('Preferencias guardadas.');}catch(e){$('#pref-message').textContent=errorText(e);}finally{saving=false;}};}
