async function importFiles(ev){const files=[...ev.target.files];ev.target.value='';if(!requireAccount()||!files.length)return;try{if(draft){if(files.some(f=>f.size>10*1024*1024))throw Error('Cada GPX debe ocupar menos de 10 MB.');if(files.length>1)throw Error('Importa un solo GPX dentro de una ficha.');if(draft.data.points.length&&!confirm('¿Sustituir el trazado del borrador por este GPX?'))return;const parsed=parseGPX(await files[0].text());draft.data={...draft.data,...parsed};if(!draft.title)draft.title=parsed.title;stashDraft();showEditor();return;}const parsedFiles=[];for(const file of files){if(file.size>10*1024*1024)throw Error('Cada GPX debe ocupar menos de 10 MB.');parsedFiles.push(parseGPX(await file.text()));}importQueue=parsedFiles;nextImport();}catch(e){toast(errorText(e));}}
