async function delegated(ev){const photo=ev.target.closest('[data-photo]');if(photo){showPhoto(photo.dataset.photo,photo.dataset.photoName);return;}const recovery=ev.target.closest('[data-undo-draft-item]');if(recovery&&draft){const index=draftItemUndos.findIndex(u=>u.token===recovery.dataset.undoDraftItem&&u.draftId===draft.id);if(index>=0){draft.data=restoreDraftItem(draft.data,draftItemUndos[index].undo);draftItemUndos.splice(index,1);stashDraft();renderDraft();}return;}const rm=ev.target.closest('[data-remove-marker],[data-remove-photo]');if(rm&&draft){const key=rm.dataset.removeMarker?'markers':'photos',id=rm.dataset.removeMarker||rm.dataset.removePhoto;if(key==='photos'&&!confirm('¿Quitar esta foto de la galería y de sus marcadores? No se borra del almacenamiento.'))return;const result=removeDraftItem(draft.data,key,id);if(result){draft.data=result.data;draftItemUndos.push({token:crypto.randomUUID(),draftId:draft.id,undo:result.undo});stashDraft();renderDraft();}return;}const menu=ev.target.closest('[data-menu]');if(menu){const what=menu.dataset.menu;closeDialogs();({draft:showEditor,places:showPlaces,plans:showPlans,import:()=>{if(!requireAccount())return;$('#gpx-input').multiple=true;$('#gpx-input').click();},preferences,help:showHelp,account}[what])?.();return;}const b=ev.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,e=entries.find(x=>x.id===id);switch(b.dataset.action){case'new':newEntry();break;case'plan':newEntry('plan');break;case'view-adventure':viewAdventure(id);break;case'focus-adventure-map':$('#map-wrap').scrollIntoView({block:'center'});fitSelectedRoute();break;case'detail':case'route-place':detail(id);break;case'edit':edit(id);break;case'delete':await deleteEntry(id);break;case'goal':goalForm();break;case'coast-info':coastInfo();break;case'new-place':if(requireAccount())markerForm();break;case'place-detail':placeDetail(id);break;case'edit-place':if(draft){toast('Resuelve el borrador antes de editar lugares.');break;}markerForm(e.data.point,false,e);break;case'windy-place':window.open(`https://www.windy.com/?${e.data.point[0]},${e.data.point[1]},14`,'_blank','noopener');break;case'locate':viewAdventure(id);break;case'export':{const url=URL.createObjectURL(new Blob([exportGPX(e)],{type:'application/gpx+xml'}));const a=document.createElement('a');a.href=url;a.download=`paleando-${e.id}.gpx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'complete':if(draft){toast('Resuelve el borrador antes de registrar la ruta como realizada.');break;}draft={...structuredClone(e),kind:'trip',title:e.title,data:{...structuredClone(e.data),duration:'',date:today(),fromPlan:e.id}};stashDraft();showEditor();toast('Revisa la fecha y los datos antes de guardar como salida realizada.');break;case'practice':startPractice();break;case'sync':closeDialogs();sync();break;case'logout':logout();break;case'marker-photo':{const m=e.data.markers.find(m=>m.id===b.dataset.marker);const p=e.data.photos.find(p=>p.id===m.photoId);if(p)showPhoto(p.path,p.name);break;}}}
async function boot(){bind();initMap();recoverDraft();render();try{const c=await getClient();const {data,error}=await c.auth.getSession();if(error)throw error;user=data.session?.user||null;recoverDraft();if(user)await sync();c.auth.onAuthStateChange((event,session)=>{const next=session?.user||null;if(user?.id===next?.id)return;if(practice)endPractice();if(draft)stashDraft();resetWeatherTransient();conflictState=null;draftItemUndos=[];accountEpoch++;syncVersion++;loadedAccount=null;loading=false;clearTimeout(undoTimer);undoEntry=null;importQueue=[];weatherRequest++;photoRequest++;closeDialogs();mode=null;$('#draw-bar').hidden=true;$('#map-hint').hidden=true;user=next;entries=[];draft=null;recoverDraft();render();if(user)setTimeout(async()=>{await sync();offerLoginGuide();},0);else state('Sin iniciar sesión · v0.6.0');});render();}catch(e){state('Conexión de cuenta no disponible');toast('No se pudo conectar con la cuenta. El mapa sigue disponible. Recarga para reintentar.');}}
boot();

function readFormIfOpen(){if($('#editor-dialog').open)readForm();}

async function hydratePhotos(root){for(const button of root.querySelectorAll('[data-photo]')){const path=button.dataset.photo;const image=document.createElement('img');image.alt=button.dataset.photoName||'Fotografía';image.loading='lazy';button.prepend(image);try{const url=path==='example'?'./guide-photo.svg':await signedPhoto(path);if(!button.isConnected)continue;image.src=url;image.onerror=()=>{image.remove();button.title='No se pudo cargar la vista previa. Pulsa para reintentar.';};}catch{image.remove();button.title='Vista previa no disponible. Pulsa para reintentar.';}}}

function prepareEstimate(){const plan=draft.kind==='plan';$('#plan-estimate').hidden=!plan;$('#real-duration').hidden=plan;if(!plan)return;if(draft.data.estimatedMinutes==null&&draft.data.duration!==''&&draft.data.duration!=null){draft.data.estimatedMinutes=Number(draft.data.duration);draft.data.estimateMode='manual';}const prefs=active('preferences')[0]?.data||{};$('#entry-form [name=pace]').value=draft.data.paceMinutesPerKm||prefs.paceMinutesPerKm||15;$('#entry-form [name=stops]').value=draft.data.stopMinutes??0;$('#estimate-manual').checked=draft.data.estimateMode==='manual';if(draft.data.estimateMode==='manual')$('#entry-form [name=estimate]').value=draft.data.estimatedMinutes;refreshEstimate();}
function refreshEstimate(){if(draft?.kind!=='plan')return;const f=$('#entry-form');try{draft.data.paceMinutesPerKm=Number(f.elements.pace.value||draft.data.paceMinutesPerKm||15);draft.data.stopMinutes=Number(f.elements.stops.value||0);draft.data=updatePlanEstimate(draft.data,active('preferences')[0]?.data||{});f.elements.estimate.value=draft.data.estimatedMinutes;f.elements.estimate.readOnly=draft.data.estimateMode!=='manual';$('#estimate-copy').textContent=`${durationText(draft.data.estimatedMinutes)} · ${draft.data.estimateMode==='manual'?'duración manual conservada':'calculada con '+draft.data.paceMinutesPerKm+' min/km y '+draft.data.stopMinutes+' min de paradas'}`;}catch(e){$('#estimate-copy').textContent=errorText(e);}}
function fitSelectedRoute(){const e=entries.find(e=>e.id===selectedRouteId);if(!e||!validGeometry(e.data.points)||!map)return;map.invalidateSize();map.fitBounds(e.data.points,{paddingTopLeft:[24,45],paddingBottomRight:[82,45],maxZoom:16,animate:false});}
function viewAdventure(id){const e=entries.find(e=>e.id===id&&!e.deleted_at);if(!e){toast('No se encuentra esta aventura.');return;}readFormIfOpen();if(draft)stashDraft();closeDialogs();mode=null;$('#draw-bar').hidden=true;$('#map-hint').hidden=true;$('#layers').hidden=true;$('[data-map=layers]').setAttribute('aria-expanded','false');switchTab('mapa');selectedRouteId=id;refreshSelectedRoute();$('#adventure-panel').scrollIntoView({block:'start'});fitSelectedRoute();setTimeout(fitSelectedRoute,80);}
function refreshSelectedRoute(){if(!selectedRouteId)return;const e=entries.find(e=>e.id===selectedRouteId&&!e.deleted_at);selectionLayer?.clearLayers();if(!e){selectedRouteId=null;adventurePhotoVersion++;$('#selected-route').hidden=true;$('#adventure-panel').hidden=true;$('#adventure-map-notice').hidden=true;return;}renderAdventurePanel(e);const style=routeStyle(e);$('#selected-route-name').textContent=e.title;$('#selected-route-type').textContent=style.icon+' '+style.label;$('#selected-route').style.setProperty('--route-color',style.color);$('#selected-route').dataset.routeId=e.id;$('#selected-route').hidden=false;const valid=validGeometry(e.data?.points);$('#adventure-map-notice').hidden=valid;$('#adventure-map-notice').textContent=valid?'':'Esta aventura no tiene una geometría válida. Puedes consultar su ficha y editarla; no hay un recorrido que encuadrar.';if(valid&&selectionLayer){L.polyline(e.data.points,{color:'#fff',weight:10,opacity:1,interactive:false}).addTo(selectionLayer);L.polyline(e.data.points,{color:style.color,weight:6,opacity:1,interactive:false}).addTo(selectionLayer);}}
function renderAdventurePanel(entry){const generation=++adventurePhotoVersion,panel=$('#adventure-panel'),photos=entry.data.photos||[],photo=photos.find(p=>typeof p.path==='string'&&p.path.trim());panel.hidden=false;panel.dataset.routeId=entry.id;$('#adventure-sheet').innerHTML=adventureMarkup(entry);hydratePhotos($('#adventure-sheet'));const figure=$('#adventure-image');figure.hidden=!photo;figure.innerHTML='';if(!photo)return;const button=document.createElement('button');button.type='button';button.dataset.photo=photo.path||'example';button.dataset.photoName=photo.name||entry.title;button.className='adventure-photo-button';button.setAttribute('aria-label','Ver fotografía de '+entry.title);const image=document.createElement('img');image.alt=photo.name||entry.title;const caption=document.createElement('figcaption');caption.textContent='Cargando fotografía…';button.append(image);figure.append(button,caption);image.onload=()=>{if(generation===adventurePhotoVersion)caption.textContent=photo.name||'Fotografía de la aventura';};image.onerror=()=>{if(generation===adventurePhotoVersion){button.remove();caption.textContent='No se pudo cargar la fotografía. Puedes reintentarlo desde Fotografías.';}};(async()=>{try{const url=photo.path==='example'?'./guide-photo.svg':await signedPhoto(photo.path);if(generation!==adventurePhotoVersion||selectedRouteId!==entry.id)return;image.src=url;}catch{if(generation===adventurePhotoVersion){button.remove();caption.textContent='No se pudo cargar la fotografía privada. Puedes reintentarlo desde Fotografías.';}}})();}

function renderItemUndos(){if(!draft)return;for(const record of draftItemUndos.filter(u=>u.draftId===draft.id)){const b=document.createElement('button');b.type='button';b.className='text-button';b.dataset.undoDraftItem=record.token;b.textContent=`↩ Recuperar ${record.undo.key==='photos'?'fotografía':'marcador'}: ${record.undo.item.name||record.undo.item.title||''}`;$('#draft-'+(record.undo.key==='photos'?'photos':'markers')).append(b);}}
async function showConflict(){if(!draft||!user)return;const epoch=accountEpoch,local=structuredClone(draft);stashDraft();content('Revisar conflicto de guardado','<p role="status">Cargando la versión guardada. Tu borrador se conserva.</p>');try{const rows=await loadEntries();if(epoch!==accountEpoch||draft?.id!==local.id)return;const latest=rows.find(e=>e.id===local.id);conflictState={epoch,local,latest};const fields=latest&&!latest.deleted_at?conflictFields(local,latest):[];$('#content-body').innerHTML=`<p>Tu borrador se conserva. ${latest?.deleted_at?'La ficha se eliminó en otra sesión.':!latest?'La ficha ya no está disponible.':'Elige qué conservar en cada campo diferente. Nada se sobrescribe hasta que revises y guardes.'}</p>${latest&&!latest.deleted_at?`<form id="conflict-form">${fields.map((f,i)=>`<fieldset><legend>${esc(f.label)}</legend><p>Mi borrador: ${esc(conflictSummary(f.local))}</p><p>Servidor: ${esc(conflictSummary(f.server))}</p><label>Conservar<select name="choice-${i}" required><option value="">Elige una versión</option><option value="local">Mi borrador</option><option value="server">Servidor</option></select></label></fieldset>`).join('')}<button class="button primary">Combinar y revisar antes de guardar</button></form><button id="conflict-server" class="text-button">Usar versión del servidor</button>`:''}<button id="conflict-copy" class="button secondary">Conservar mi borrador como otra salida</button><button id="conflict-continue" class="text-button">Seguir editando mi borrador</button><p id="conflict-message" role="status"></p>`;if($('#conflict-form'))$('#conflict-form').onsubmit=ev=>{ev.preventDefault();if(epoch!==accountEpoch)return;try{const choices=Object.fromEntries(fields.map((f,i)=>[f.id,ev.target.elements['choice-'+i].value]));draft=mergeConflict(local,latest,choices);draftItemUndos=[];stashDraft();showEditor();$('#editor-message').textContent='Revisa la versión combinada y pulsa Guardar. Si vuelve a cambiar en otra sesión, te avisaremos.';}catch(e){$('#conflict-message').textContent=errorText(e);}};if($('#conflict-server'))$('#conflict-server').onclick=()=>{if(epoch!==accountEpoch)return;if(!confirm('¿Descartar los cambios de este borrador y abrir la versión guardada del servidor?'))return;draft=structuredClone(latest);draftItemUndos=[];stashDraft();showEditor();};$('#conflict-copy').onclick=()=>{if(epoch!==accountEpoch)return;draft={id:crypto.randomUUID(),kind:local.kind,title:(local.title.slice(0,165)+' (copia)'),data:structuredClone(local.data)};draftItemUndos=[];stashDraft();showEditor();};$('#conflict-continue').onclick=()=>{if(epoch!==accountEpoch)return;showEditor();};}catch(e){if(epoch!==accountEpoch)return;$('#content-body').textContent='No se pudo cargar la otra versión. Tu borrador sigue conservado. '+errorText(e);const retry=document.createElement('button');retry.className='button secondary';retry.textContent='Reintentar comparación';retry.onclick=showConflict;$('#content-body').append(retry);}}
